package gadomancymodern.node;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.AABB;
import tc4revival.content.*;
/** The original two-stage, 600-tick destructive overfeeding event. */
public class GrowingVortexExplosion {
    public final ExtendedNodeEntity node;public int phase,ticks;public final List<BlockPos> pending=new ArrayList<>();
    public GrowingVortexExplosion(ExtendedNodeEntity node){this.node=node;}
    public boolean finished(){return phase>1;}
    public void tick(){if(!(node.getLevel() instanceof ServerLevel level)||node.isRemoved())return;var pos=node.getBlockPos();for(var living:level.getEntitiesOfClass(LivingEntity.class,new AABB(pos).inflate(6)))if(living.isAlive()&&!living.isInvulnerable()&&!(living instanceof Player p&&p.getAbilities().instabuild)&&level.random.nextInt(16)==0){living.hurt(level.damageSources().magic(),4);NodeVisualNetwork.bolt(level,pos.getCenter(),living.position().add(0,living.getBbHeight(),0),0);}if(phase<2&&level.random.nextInt(phase==0?8:4)==0){NodeVisualNetwork.burst(level,pos);level.playSound(null,pos,TCSounds.ICE.get(),net.minecraft.sounds.SoundSource.BLOCKS,.8f,1);}ticks++;if(phase==0){randomBolt(level,pos);if(ticks>200){ticks=0;phase=1;explode(level,pos,false,1);}return;}if(phase!=1)return;for(var removed:pending){if(level.hasChunkAt(removed))level.removeBlock(removed,false);randomBolt(level,pos);}pending.clear();for(int i=level.random.nextInt(4);i>0;i--)randomBolt(level,pos);int range=ticks>300?9:ticks>200?7:ticks>100?6:ticks>75?5:ticks>50?4:3;for(int i=0;i<10;i++){var at=pos.offset(level.random.nextInt(range)-level.random.nextInt(range),level.random.nextInt(range)-level.random.nextInt(range),level.random.nextInt(range)-level.random.nextInt(range));if(!level.hasChunkAt(at))continue;var state=level.getBlockState(at);float hardness=state.getDestroySpeed(level,at);if(state.isAir()||hardness<=0||hardness>50||state.getBlock() instanceof AuraNodeBlock)continue;pending.add(at);NodeVisualNetwork.absorb(level,at,pos.getCenter(),7);}if(ticks==200||ticks==300)explode(level,pos,false,1);if(ticks>400){phase=2;var base=node.permanentBase();var charge=node.portableCharge();for(var aspect:base.aspects())if(level.random.nextInt(4)==0){base.remove(aspect);charge.remove(aspect);}else base.reduce(aspect,base.amount(aspect)/2);for(var aspect:charge.aspects())charge.reduce(aspect,charge.amount(aspect)/2);node.configure(base,node.permanentType(),node.permanentModifier(),node.nodeId(),true);for(var aspect:charge.aspects())node.addCharge(aspect,Math.min(base.amount(aspect),charge.amount(aspect)));explode(level,pos,true,3);}}
    public static void randomBolt(ServerLevel level,BlockPos pos){var random=level.random;var target=pos.getCenter().add(random.nextInt(3)-random.nextInt(3)+(random.nextBoolean()?1:-1)*random.nextFloat(),random.nextInt(3)-random.nextInt(3)+(random.nextBoolean()?1:-1)*random.nextFloat(),random.nextInt(3)-random.nextInt(3)+(random.nextBoolean()?1:-1)*random.nextFloat());NodeVisualNetwork.bolt(level,pos.getCenter(),target,0);}
    public static void explode(ServerLevel level,BlockPos pos,boolean taint,int chance){level.explode(null,pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5,3,false,Level.ExplosionInteraction.NONE);for(int i=0;i<80;i++){var at=pos.offset(level.random.nextInt(10)-level.random.nextInt(10),level.random.nextInt(10)-level.random.nextInt(10),level.random.nextInt(10)-level.random.nextInt(10));if(!level.hasChunkAt(at))continue;if(level.isEmptyBlock(at)){var state=(at.getY()<pos.getY()?TCArcane.FLUX_GOO.get():TCArcane.FLUX_GAS.get()).defaultBlockState();for(var property:state.getProperties())if(property.getName().equals("level")&&property instanceof net.minecraft.world.level.block.state.properties.IntegerProperty value&&value.getPossibleValues().contains(8))state=state.setValue(value,8);level.setBlockAndUpdate(at,state);}if(taint&&tc4revival.config.TCConfig.SERVER.generates(tc4revival.config.TCConfig.WorldFeature.TAINT)&&level.random.nextInt(Math.max(1,chance))==0)WorldBiomeChanges.changeColumn(level,at,TCBiomes.TAINTED_LAND);}}
}
